#!/usr/bin/env perl
# PLANSEL Weinwelt: Asset-Klassen der Welt. Nur Perl-Kernmodule, curl und unzip. Aufruf: perl assets.pl <Ordner data>
# Höchstens alle 20 Stunden (FORCE=1 erzwingt). Fällt eine Quelle aus, bleibt ihr letzter Wert aus assets.json stehen.
use strict; use warnings; use utf8; use JSON::PP; use POSIX qw(strftime); use File::Temp qw(tempfile);
binmode STDOUT, ":utf8"; my $D = shift // 'monitor/data'; my $J = JSON::PP->new->utf8->canonical; my $now = time; my $iso = strftime('%Y-%m-%dT%H:%M:%SZ', gmtime $now);
sub slurp { my $f = shift; open my $i, '<:raw', $f or return; local $/; <$i> }
my $B = $J->decode(slurp("$D/assets-base.json")); my $R = $J->decode(slurp("$D/assets-reg.json")); my $old = eval { $J->decode(slurp("$D/assets.json") // '{}') } || {};
if ($old->{ts} && $now - $old->{ts} < 20 * 3600 && !$ENV{FORCE}) { print "assets.json ist aktuell\n"; exit }
my (%v, @log);
sub get { my ($u) = @_; for my $try (1 .. 3) { open my $p, '-|', 'curl', '-sL', '--compressed', '-m', '60', '-A', 'PlanselWineMonitor/1.0', '-w', "\n%{http_code}", $u or die 'curl'; binmode $p; local $/; my $b = <$p>; close $p; my ($c) = $b =~ /\n(\d+)\z/; $b =~ s/\n\d+\z//; return $b if ($c // 0) == 200; die "HTTP " . ($c // 0) . "\n" if $try == 3; sleep 4 * $try } }
sub rng { my ($x, $lo, $hi, $n) = @_; die "unplausibel $n: " . ($x // 'leer') . "\n" unless defined $x && $x >= $lo && $x <= $hi; $x + 0 }
# Ein Wert je Schlüssel: [Zahl, Stand]
sub val { my ($k, $code) = @_; my $r = eval { $code->() }; if ($r) { $v{$k} = $r } else { my $e = $@ || 'leer'; chomp $e; push @log, "$k: $e"; $v{$k} = $old->{raw}{$k} if $old->{raw}{$k} } }
val('usd', sub { my @a = split /\r?\n/, get('https://www.federalreserve.gov/datadownload/Output.aspx?rel=H6&series=798e2796917702a5f8423426ba7e6b42&lastobs=3&from=&to=&filetype=csv&label=include&layout=seriescolumn'); my ($h) = grep { /^"Time Period"/ } @a; my ($l) = reverse grep { /^"?\d{4}-\d\d/ } @a; my @h = map { s/"//gr } split /,/, $h; my @c = map { s/"//gr } split /,/, $l; my ($i) = grep { $h[$_] eq 'M2.M' } 0 .. $#h; [ rng($c[$i], 15e3, 60e3, 'M2 Dollar') * 1e9, $c[0] ] });
val('eurM', sub { my ($l) = reverse grep { /^BSI/ } split /\r?\n/, get('https://data-api.ecb.europa.eu/service/data/BSI/M.U2.Y.V.M20.X.1.U2.2300.Z01.E?lastNObservations=1&format=csvdata&detail=dataonly'); my @f = split /,/, $l; [ rng($f[-1], 10e6, 40e6, 'M2 Euro') * 1e6, $f[-2] ] });
val('jpyM', sub { my $o = $J->decode(get('https://www.stat-search.boj.or.jp/api/v1/getDataCode?db=MD02&code=MAM1NAM2M2MO&format=json&lang=en&startDate=' . strftime('%Y%m', gmtime($now - 86400 * 130)))); my $x = $o->{RESULTSET}[0]{VALUES}; my $d = $x->{SURVEY_DATES}[-1]; $d =~ s/^(\d{4})(\d\d)$/$1-$2/; [ rng($x->{VALUES}[-1], 8e6, 30e6, 'M2 Yen') * 1e8, $d ] });
my %fx; { my $c = eval { get('https://data-api.ecb.europa.eu/service/data/EXR/D.USD+JPY+CNY+INR.EUR.SP00.A?lastNObservations=1&format=csvdata&detail=dataonly') }; if ($c) { for (split /\r?\n/, $c) { my @f = split /,/; $fx{ $f[2] } = [ $f[7] + 0, $f[6] ] if $f[0] =~ /^EXR/ } } }
for my $c (qw(USD JPY CNY INR)) { my $x = $fx{$c}; val("fx$c", sub { $x || die "fehlt\n" }) }
val('btc', sub { my $o = $J->decode(get('https://api.coinpaprika.com/v1/tickers/btc-bitcoin')); [ rng($o->{quotes}{USD}{price}, 1e3, 1e6, 'Bitcoin'), substr $o->{last_updated}, 0, 10 ] });
val('btcN', sub { [ rng(get('https://blockchain.info/q/totalbc') / 1e8, 19e6, 21e6, 'BTC'), substr $iso, 0, 10 ] });
val('crypto', sub { my $o = $J->decode(get('https://api.coinpaprika.com/v1/global')); [ rng($o->{market_cap_usd}, 2e11, 3e13, 'Krypto'), substr $iso, 0, 10 ] });
# BIS: Kredite an Staat, Haushalte und Unternehmen, Mrd. US-Dollar
val('bis', sub { my %o; my $per; for (split /\r?\n/, get('https://stats.bis.org/api/v2/data/dataflow/BIS/WS_TC/2.0/Q.US+CN+IN+JP+XM+5A.C.A.M.USD.A?lastNObservations=1&format=csv')) { next unless /^Q,(\w\w),/; my $c = $1; my ($p, $x) = /,(\d{4}-Q\d),([\d.]+),/ or next; $o{$c} = $x * 1e9; $per = $p } rng($o{'5A'}, 2e14, 6e14, 'BIS Welt'); rng($o{US}, 5e13, 2e14, 'BIS USA'); $per =~ s/-Q(\d)/sprintf '-%02d', $1 * 3/e; [ { W => $o{'5A'}, US => $o{US}, CN => $o{CN}, IN => $o{IN}, EU => $o{XM}, JP => $o{JP} }, $per ] });
# Geldmenge der Welt: Weltbank, Anteil am BIP mal BIP desselben Jahres
val('m2w', sub { my $f = sub { my $d = $J->decode(get("https://api.worldbank.org/v2/country/WLD/indicator/$_[0]?format=json&$_[1]")); $d->[1][0] || die "leer\n" }; my $x = $f->('FM.LBL.BMNY.GD.ZS', 'mrnev=1'); my $g = $f->('NY.GDP.MKTP.CD', "date=$x->{date}"); [ rng($x->{value} / 100 * $g->{value}, 8e13, 4e14, 'M2 Welt'), $x->{date} ] });
$v{uran} = [ $B->{uran}{v}, $B->{uran}{per} ];
# Weltbank-Rohstoffpreise (Pink Sheet, CC BY 4.0)
my %wb; eval { my ($u) = get('https://www.worldbank.org/en/research/commodity-markets') =~ m{(https?://[^"]*CMO-Historical-Data-Monthly\.xlsx)} or die "Link fehlt\n"; my ($fh, $fn) = tempfile(SUFFIX => '.xlsx', UNLINK => 1); binmode $fh; print $fh get($u); close $fh;
  my $z = sub { open my $p, '-|', 'unzip', '-p', $fn, $_[0] or die; binmode $p; local $/; <$p> }; my @s; my $x = $z->('xl/sharedStrings.xml'); while ($x =~ /<si>(.*?)<\/si>/gs) { my $t = $1; $t =~ s/<[^>]+>//g; push @s, $t }
  my ($rid) = $z->('xl/workbook.xml') =~ /<sheet name="Monthly Prices"[^>]*r:id="(rId\d+)"/ or die "Blatt\n"; my ($tg) = $z->('xl/_rels/workbook.xml.rels') =~ /<Relationship [^>]*?Id="$rid"[^>]*?Target="([^"]+)"|$/; unless ($tg) { ($tg) = $z->('xl/_rels/workbook.xml.rels') =~ /Target="([^"]+)"[^>]*?Id="$rid"/ } $tg =~ s{^/?(xl/)?}{};
  my $d = $z->("xl/$tg"); my %r; while ($d =~ /<c r="([A-Z]+)(\d+)"([^>]*?)(?:\/>|>(.*?)<\/c>)/gs) { my ($c, $n, $a, $b) = ($1, $2, $3, $4); next unless defined $b; my ($w) = $b =~ /<v>(.*?)<\/v>/; next unless defined $w; $w = $s[$w] if $a =~ /t="s"/; $r{$n}{$c} = $w }
  my ($h) = sort { $a <=> $b } grep { ($r{$_}{BR} // '') eq 'Gold' || grep { $_ eq 'Gold' } values %{ $r{$_} } } keys %r; my ($l) = sort { $b <=> $a } grep { ($r{$_}{A} // '') =~ /^\d{4}M\d\d$/ } keys %r; (my $per = $r{$l}{A}) =~ s/M/-/;
  for my $c (keys %{ $r{$h} }) { my $n = $r{$h}{$c}; $n =~ s/[\s*]+$//; my $w = $r{$l}{$c}; $wb{$n} = [ $w + 0, $per ] if defined $w && $w =~ /^[\d.]+(?:E[+-]?\d+)?$/ } 1 } or push @log, "Weltbank: $@";
my %m = (oil => ['Crude oil, average', 10, 400], gold => ['Gold', 500, 30000], silver => ['Silver', 5, 500], plat => ['Platinum', 200, 10000], copper => ['Copper', 2000, 60000], iron => ['Iron ore, cfr spot', 20, 500], nickel => ['Nickel', 4000, 100000], zinc => ['Zinc', 800, 20000], lead => ['Lead', 600, 10000], tin => ['Tin', 8000, 200000], phosphate => ['Phosphate rock', 30, 1000], potash => ['Potassium chloride', 80, 2000]);
for my $k (sort keys %m) { my ($n, $lo, $hi) = @{ $m{$k} }; val($k, sub { my $x = $wb{$n} or die "fehlt: $n\n"; [ rng($x->[0], $lo, $hi, $n), $x->[1] ] }) }
val('coal', sub { my ($a, $b) = ($wb{'Coal, Australian'}, $wb{'Coal, South African'}); die "fehlt\n" unless $a && $b; [ rng(($a->[0] + $b->[0]) / 2, 20, 600, 'Kohle'), $a->[1] ] });
val('gas', sub { my @g = map { $wb{$_} // die "fehlt: $_\n" } 'Natural gas, US', 'Natural gas, Europe', 'Liquefied natural gas, Japan'; [ rng(($g[0][0] + $g[1][0] + $g[2][0]) / 3, 1, 100, 'Gas'), $g[0][1] ] });
$v{pgm} = [ ($v{plat}[0] + $B->{palladium}) / 2, $v{plat}[1] ] if $v{plat};
for my $k (qw(usd eurM jpyM fxUSD fxJPY fxCNY fxINR btc btcN gold oil gas coal copper)) { die "ohne Wert: $k\n" unless $v{$k} }
my @row; for (@{ $B->{fixed} }) { my %e = %$_; if ($e{id} eq 'debt' && $v{bis}) { my %b = %{ $v{bis}[0] }; my $w = delete $b{W}; %e = (%e, v => $w, per => $v{bis}[1], src => 'BIS', url => 'https://data.bis.org/topics/TOTAL_CREDIT', reg => \%b) } push @row, \%e } my $usdjpy = $v{fxJPY}[0] / $v{fxUSD}[0]; my $usdcny = $v{fxCNY}[0] / $v{fxUSD}[0];
my $ECB = 'https://data.ecb.europa.eu/';
my $usdinr = $v{fxINR}[0] / $v{fxUSD}[0];
push @row, { id => 'cash', k => 'money', n => 'Cash (Fiat)', v => $v{m2w}[0], per => $v{m2w}[1], src => 'World Bank', url => 'https://data.worldbank.org/indicator/FM.LBL.BMNY.GD.ZS', more => [ [ 'USA', 'Federal Reserve', 'https://www.federalreserve.gov/releases/h6/current/default.htm', $v{usd}[1] ], [ 'China', $B->{cny}{src}, $B->{cny}{url}, $B->{cny}{per} ], [ 'Indien', 'RBI', 'https://tradingeconomics.com/india/money-supply-m3', '10.2026' ], [ 'EU', 'EZB', $ECB, $v{eurM}[1] ], [ 'Japan', 'Bank of Japan', 'https://www.stat-search.boj.or.jp/index_en.html', $v{jpyM}[1] ] ],
  reg => { US => $v{usd}[0], CN => $B->{cny}{v} / $usdcny, IN => $R->{inr}{m2} / $usdinr, EU => $v{eurM}[0] * $v{fxUSD}[0], JP => $v{jpyM}[0] / $usdjpy } } if $v{m2w};
my $g = $B->{goldstock}; push @row, { id => 'gold', k => 'metal', n => 'Gold, bereits gefördert', v => $g->{t} * 32150.75 * $v{gold}[0], q => $g->{t}, u => 't', price => $v{gold}[0], pu => 'oz', per => $v{gold}[1], src => "$g->{src}, World Bank", url => $g->{url} };
my $bt = $v{btc}[0] * $v{btcN}[0]; push @row, { id => 'btc', k => 'metal', n => 'Bitcoin', v => $bt, q => $v{btcN}[0], u => 'BTC', price => $v{btc}[0], pu => 'BTC', per => $v{btc}[1], src => 'Coinpaprika, Blockchain.com', url => 'https://coinpaprika.com/coin/btc-bitcoin/' };
push @row, { id => 'crypto', k => 'metal', n => 'Übrige Kryptowährungen', v => $v{crypto}[0] - $bt, per => $v{crypto}[1], src => 'Coinpaprika', url => 'https://coinpaprika.com/' } if $v{crypto} && $v{crypto}[0] > $bt;
my %pu = (oil => 'bbl', gas => 'MMBtu', coal => 't', uran => 'lb', gold => 'oz', silver => 'oz', pgm => 'oz', potash => 't');
for my $r (@{ $B->{res} }) { my $us = $r->{us} ? $B->{usgs} : undef; my ($pr, $f, $per, $pu); if ($r->{fix}) { ($pr, $f, $per, $pu) = ($r->{fix}, 1, '2025', 't') } else { my $x = $v{ $r->{p} } or do { push @log, "$r->{id}: kein Preis"; next }; ($pr, $f, $per, $pu) = ($x->[0], $r->{f}, $x->[1], $pu{ $r->{p} } // 't') }
  push @row, { id => $r->{id}, k => 'res', n => $r->{n}, v => $r->{q} * $f * $pr, q => $r->{q}, u => $r->{u}, price => $pr, pu => $pu, per => $per, src => ($us ? 'USGS 2026' : $r->{src}) . ($r->{fix} ? '' : $r->{p} eq 'uran' ? ', IMF' : ', World Bank'), url => $us ? "$us->{base}$r->{us}.pdf" : $r->{url} } }
for my $r (@row) { my $id = $r->{id}; my %g = %{ $r->{reg} || $R->{v}{$id} || {} }; $g{IN} = $R->{inr}{stocks} / ($v{fxINR}[0] / $v{fxUSD}[0]) if $id eq 'stocks'; if (my $q = $R->{q}{$id}) { $g{$_} = $r->{v} * $q->{$_} / $r->{q} for grep { $q->{$_} } keys %$q } if ($id eq 'gold') { $g{$_} = $R->{gold}{$_} * 32150.75 * $v{gold}[0] for keys %{ $R->{gold} } } $g{$_} = int($g{$_} / 1e8 + .5) * 1e8 for keys %g; $r->{reg} = \%g if %g }
@row = sort { $b->{v} <=> $a->{v} } @row; $_->{v} = int($_->{v} / 1e8 + .5) * 1e8 for @row;
my %o = (ts => $now, generated => $iso, raw => \%v, log => \@log, rows => \@row, gdp => $v{gdp} ? { reg => $v{gdp}[0], per => $v{gdp}[1] } : undef, open => [ map { { %$_, src => 'USGS 2026', url => $B->{usgs}{base} . "$_->{us}.pdf" } } @{ $B->{open} } ]);
open my $f, '>:raw', "$D/assets.json.neu" or die; print $f $J->encode(\%o); close $f; rename "$D/assets.json.neu", "$D/assets.json" or die;
my $i = 0; printf "%2d %-42s %10.3f Bio. %s\n", ++$i, $_->{n}, $_->{v} / 1e12, $_->{per} for @row; print "Hinweise: ", join('; ', @log) || 'keine', "\n";
